from pathlib import Path
import base64
import io
import zipfile

ROOT = Path(__file__).resolve().parents[1]
PAYLOAD_B64 = ''


def main():
    payload = base64.b64decode(PAYLOAD_B64)
    with zipfile.ZipFile(io.BytesIO(payload)) as zf:
        zf.extractall(ROOT)
        for name in zf.namelist():
            print(f"APPLIED: {name}")

    zip_path = ROOT / "phase5_vssf_broker_control.zip"
    members = [
        "option_program/broker/broker_interface.py",
        "virtual_securities_firm/runtime/firm_runtime.py",
        "web_interface/server.py",
        "tests/src/test_vssf_broker_control.py",
        "tools/apply_phase5_vssf_broker_control.py",
    ]
    with zipfile.ZipFile(zip_path, "w", compression=zipfile.ZIP_DEFLATED) as out:
        for rel_path in members:
            target = ROOT / rel_path
            if not target.exists():
                raise FileNotFoundError(target)
            out.write(target, arcname=rel_path)
    print(f"ZIP_CREATED: {zip_path}")


if __name__ == "__main__":
    main()
